import React, { useEffect, useState } from "react";

import AdminBookingTable from "../components/AdminBookingTable";
import AdminLayout from "../components/AdminLayout";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const cards = [
  ["total_users", "Total Users"],
  ["total_teachers", "Total Teachers"],
  ["total_students", "Total Students"],
  ["total_bookings", "Total Bookings"],
  ["pending", "Pending Bookings"],
  ["approved", "Approved Bookings"],
  ["rejected", "Rejected Bookings"],
  ["today", "Today's Bookings"],
  ["upcoming", "Upcoming Bookings"],
];

const AdminDashboard = () => {
  const { fetchInitialData } = useAppContext();
  const [data, setData] = useState(null);
  const [message, setMessage] = useState("");
  const [refreshing, setRefreshing] = useState(false);

  const load = async () => {
    const [dashboardResponse] = await Promise.all([
      api.get("/admin/dashboard", { cache: false }),
      fetchInitialData?.(),
    ]);
    setData(dashboardResponse.data);
  };

  useEffect(() => {
    load().catch((error) => setMessage(formatErrorMessage(error.response?.data?.detail, "Could not load dashboard")));
  }, []);

  const refresh = async () => {
    setRefreshing(true);
    setMessage("");
    try {
      await load();
    } catch (error) {
      setMessage(formatErrorMessage(error.response?.data?.detail, "Could not refresh dashboard"));
    } finally {
      setRefreshing(false);
    }
  };

  return (
    <AdminLayout title="Dashboard" subtitle="Complete campus booking control and recent activity." onRefresh={refresh} refreshing={refreshing}>
      {message ? <div className="notice danger">{message}</div> : null}
      {!data ? (
        <div className="skeleton-grid"><div /><div /><div /><div /></div>
      ) : (
        <>
          <section className="metric-grid admin-metrics">
            {cards.map(([key, label]) => (
              <article key={key} className={`metric-card glass-panel ${key}`}>
                <span>{label}</span>
                <strong>{data.stats?.[key] ?? 0}</strong>
              </article>
            ))}
          </section>
          <section className="glass-panel section-panel">
            <div className="panel-heading">
              <span className="panel-icon">R</span>
              <div>
                <h2>Recent Booking Activity</h2>
                <p>Requester, role, block, resource, time, and status.</p>
              </div>
            </div>
            <AdminBookingTable bookings={data.recent || []} detailed />
          </section>
        </>
      )}
    </AdminLayout>
  );
};

export default AdminDashboard;
